const String androidGalleryProviderSource =
    r'''import 'package:flutter/services.dart';
import 'package:mini_program_contracts/mini_program_contracts.dart';
import 'package:mini_program_sdk/mini_program_sdk.dart';

/// Host-owned adapter generated by `miniprogram host capability init gallery`.
class AppAndroidGalleryProvider implements MiniProgramGalleryProvider {
  const AppAndroidGalleryProvider();

  static const _channel = MethodChannel('mini_program/gallery');

  @override
  Future<MiniProgramGalleryResult> pickImages(MiniProgramGalleryRequest request) async {
    Map<String, dynamic>? response;
    try {
      response = await _channel.invokeMapMethod<String, dynamic>('pickImages', {
        'selectionId': request.selectionId,
        'miniProgramId': request.miniProgramId,
        'maxImages': request.maxImages,
        'maxImageBytes': request.maxImageBytes,
        'maxTotalBytes': request.maxTotalBytes,
        'maxWidth': request.maxWidth,
        'maxHeight': request.maxHeight,
        'quality': request.quality,
      });
      if (response == null || response['images'] is! List) {
        throw const FormatException('Missing gallery metadata.');
      }
      final images = response['images'] as List;
      if (images.length > miniProgramGalleryMaxImages) {
        throw const FormatException('Too many gallery images.');
      }
      return MiniProgramGalleryResult.fromJson({
        ...response,
        'images': images.map((image) => Map<String, dynamic>.from(image as Map)).toList(),
      });
    } on MissingPluginException {
      throw const MiniProgramGalleryException(
        errorCode: MiniProgramErrorCodes.galleryUnavailable,
        message: 'The Android photo picker is not installed in this host.',
      );
    } on PlatformException catch (error) {
      final code = const {
        'gallery_unavailable', 'gallery_selection_cancelled',
        'gallery_request_in_progress', 'gallery_invalid_request',
        'gallery_limit_exceeded', 'gallery_unsupported_image',
        'gallery_storage_unavailable', 'gallery_operation_failed',
      }.contains(error.code) ? error.code : MiniProgramErrorCodes.galleryOperationFailed;
      throw MiniProgramGalleryException(errorCode: code, message: 'Android photo selection did not complete.');
    } catch (_) {
      final images = response?['images'];
      if (images is List) {
        for (final image in images.take(miniProgramGalleryMaxImages)) {
          if (image is Map && image['mediaRef'] is String) {
            try {
              await releaseMedia(MiniProgramMediaReleaseRequest(
                miniProgramId: request.miniProgramId, mediaRef: image['mediaRef'] as String,
              ));
            } catch (_) { /* Best-effort cleanup of malformed native results. */ }
          }
        }
      }
      throw const MiniProgramGalleryException(
        errorCode: MiniProgramErrorCodes.galleryInvalidResult,
        message: 'Android returned invalid photo metadata.',
      );
    }
  }

  @override
  Future<bool> cancel(String selectionId) async {
    try {
      return await _channel.invokeMethod<bool>('cancel', {'selectionId': selectionId}) ?? false;
    } on MissingPluginException { return false; }
  }

  @override
  Future<MiniProgramMediaPreviewResult> loadPreview(MiniProgramMediaPreviewRequest request) async {
    try {
      final response = await _channel.invokeMapMethod<String, dynamic>('loadPreview', {
        'miniProgramId': request.miniProgramId, 'mediaRef': request.mediaRef,
        'maxBytes': request.maxBytes,
      });
      if (response == null || response['mediaRef'] is! String ||
          response['mimeType'] is! String || response['bytes'] is! Uint8List) {
        throw const MiniProgramMediaException(
          errorCode: MiniProgramErrorCodes.mediaInvalidResult, message: 'Invalid photo preview.',
        );
      }
      return MiniProgramMediaPreviewResult(
        mediaRef: response['mediaRef'] as String, mimeType: response['mimeType'] as String,
        bytes: response['bytes'] as Uint8List,
      );
    } on MissingPluginException {
      throw const MiniProgramMediaException(
        errorCode: MiniProgramErrorCodes.mediaUnavailable, message: 'Photo preview is unavailable.',
      );
    } on PlatformException catch (error) {
      throw MiniProgramMediaException(
        errorCode: const {'media_not_owned', 'media_not_found', 'media_preview_too_large'}.contains(error.code)
            ? error.code : MiniProgramErrorCodes.mediaInvalidResult,
        message: 'The photo preview could not be loaded.',
      );
    }
  }

  @override
  Future<bool> releaseMedia(MiniProgramMediaReleaseRequest request) async {
    try {
      return await _channel.invokeMethod<bool>('releaseMedia', {
        'miniProgramId': request.miniProgramId, 'mediaRef': request.mediaRef,
      }) ?? false;
    } on MissingPluginException { return false; }
  }
}
''';
